using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() -> Kind: {personInfo.Kind}, Type: {personInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
    Console.WriteLine($"TryGetTypeInfo(Person)  -> found, Kind: {probed!.Kind}");
else
    Console.WriteLine("TryGetTypeInfo(Person)  -> not found");

// Now try a type the resolver doesn't know about (empty resolver → no types)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person) on limited -> found");
else
    Console.WriteLine("TryGetTypeInfo(Person) on limited -> not found (no exception!)");

record Person(string Name, int Age);

// A resolver that resolves nothing
class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

